def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def _info(t):
    """Adds parent[k] (-1 for the root) and depth[k]. Parents come before children in level order."""
    vals, left, right = _links(t)
    n = len(vals)
    par = [-1] * n
    depth = [0] * n
    for k in range(n):
        for c in (left[k], right[k]):
            if c != -1:
                par[c] = k
                depth[c] = depth[k] + 1
    return vals, left, right, par, depth


def spreadTime(tree, start):
    vals, left, right, par, depth = _info(tree)
    n = len(vals)
    s = vals.index(start)
    seen = [False] * n
    seen[s] = True
    frontier = [s]
    minutes = -1
    while frontier:
        minutes += 1
        nxt = []
        for x in frontier:
            for y in (left[x], right[x], par[x]):
                if y != -1 and not seen[y]:
                    seen[y] = True
                    nxt.append(y)
        frontier = nxt
    return minutes
